    public static final java.util.Map<String,String> PROXIES=new java.util.LinkedHashMap<>();
    private static void proxy(String key,String original,int col,int row){PROXIES.put(key,original);new ProxyResearchItem(key,original,col,row).registerResearchItem();}
    public static void bindProxies(){
        PROXIES.forEach((key,original)->{
            var source=ResearchCategories.getResearch(original);
            if(source==null)throw new IllegalStateException("Missing source research "+original);
            var siblings=new java.util.ArrayList<>(source.siblings());if(!siblings.contains(key))siblings.add(key);source.setSiblings(siblings.toArray(String[]::new));
        });
    }
    public static boolean syncProxies(PlayerKnowledge knowledge){
        boolean changed=false;
        for(var entry:PROXIES.entrySet())if(knowledge.isResearchComplete(entry.getValue()))changed|=knowledge.addResearch(entry.getKey());
        return changed;
    }
